"use client";

import * as React from "react";
import { ChevronDown, ListChecks, X } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PLAN: an agent's checklist, ticking itself off
 *
 *   pending   not started
 *   running   being worked on now; the ring turns into a spinner
 *   done      finished; the spinner blurs into a check that draws
 *             itself, and a strike-through draws across the label
 *   skipped   no longer needed
 *   failed    couldn't be done; the reason folds open underneath
 *
 * A thin line under the header fills as tasks finish and the count
 * rolls ("3 of 5"). When every task is settled "done" slides in
 * beside it and the plan folds into that one line.
 * ───────────────────────────────────────────────────────── */

export type PlanTaskStatus =
  "pending" | "running" | "done" | "skipped" | "failed";

export interface PlanTask {
  id?: string;
  label: string;
  /** A note under the task, e.g. why it failed or what it produced. */
  detail?: string;
  status: PlanTaskStatus;
}

export interface PlanProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  tasks: PlanTask[];
  title?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Fold into the summary once every task is settled. */
  collapseWhenDone?: boolean;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const STATUS_TEXT: Record<PlanTaskStatus, string> = {
  pending: "Not started",
  running: "In progress",
  done: "Done",
  skipped: "Skipped",
  failed: "Failed",
};

const MORPH = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** Every mark is there at once; the one for the task's status shows, and they trade places through a blur. */
function Mark({
  status,
  reduced,
}: {
  status: PlanTaskStatus;
  reduced: boolean;
}) {
  const layer = "absolute inset-0 flex items-center justify-center";
  return (
    <span aria-hidden="true" className="relative flex size-3.5 shrink-0">
      <span className={layer} style={swap(status === "pending", reduced)}>
        <span className="size-3.5 rounded-full border-[1.5px] border-border" />
      </span>
      <span className={layer} style={swap(status === "running", reduced)}>
        {/* Spins only while it's showing. */}
        <span
          className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground motion-reduce:animate-none ${status === "running" ? "animate-spin" : ""}`}
        />
      </span>
      <span className={layer} style={swap(status === "done", reduced)}>
        <svg viewBox="0 0 16 16" className="size-3.5">
          <circle cx="8" cy="8" r="8" className="fill-foreground" />
          <path
            d="M4.8 8.3l2.1 2.1 4.3-4.6"
            fill="none"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={1}
            className="stroke-background"
            style={{
              strokeDashoffset: status === "done" ? 0 : 1,
              transition:
                status === "done" && !reduced
                  ? `stroke-dashoffset 420ms ${MORPH} 140ms`
                  : "none",
            }}
          />
        </svg>
      </span>
      <span className={layer} style={swap(status === "skipped", reduced)}>
        <span className="flex size-3.5 items-center justify-center rounded-full border-[1.5px] border-border">
          <span className="h-[1.5px] w-1.5 rounded-full bg-muted-foreground" />
        </span>
      </span>
      <span className={layer} style={swap(status === "failed", reduced)}>
        <span className="flex size-3.5 items-center justify-center rounded-full bg-red-500 text-white">
          <X className="size-2.5" strokeWidth={3} />
        </span>
      </span>
    </span>
  );
}

/** A note that folds open under its task and folds shut again, keeping its words while it closes. */
function Detail({
  text,
  failed,
  reduced,
}: {
  text?: string;
  failed: boolean;
  reduced: boolean;
}) {
  const [last, setLast] = React.useState(text);
  if (text && text !== last) setLast(text);
  return (
    <span
      aria-hidden={!text || undefined}
      className="grid"
      style={{
        gridTemplateRows: text ? "1fr" : "0fr",
        opacity: text ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 420ms ${MORPH}, opacity ${text ? "320ms" : "160ms"} ${MORPH}, color 300ms`,
      }}
    >
      <span
        className={`min-h-0 overflow-hidden text-[12px] leading-5 transition-colors duration-300 ${failed ? "text-red-500" : "text-muted-foreground"}`}
      >
        <span className="block pt-0.5">{text ?? last}</span>
      </span>
    </span>
  );
}

export function Plan({
  tasks,
  title = "Plan",
  open,
  defaultOpen = true,
  onOpenChange,
  collapseWhenDone = true,
  className = "",
  ...props
}: PlanProps) {
  const reduced = useReducedMotion();
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const [touched, setTouched] = React.useState(false);
  const panelId = React.useId();

  const done = tasks.filter((t) => t.status === "done").length;
  const settled =
    tasks.length > 0 &&
    tasks.every(
      (t) =>
        t.status === "done" || t.status === "skipped" || t.status === "failed",
    );
  const failed = tasks.some((t) => t.status === "failed");
  const expanded = open ?? ownOpen;

  // Fold away once everything is settled, unless the user has taken control or something failed.
  React.useEffect(() => {
    if (
      !collapseWhenDone ||
      open !== undefined ||
      touched ||
      !settled ||
      failed
    )
      return;
    const timer = window.setTimeout(() => setOwnOpen(false), 1200);
    return () => window.clearTimeout(timer);
  }, [collapseWhenDone, open, touched, settled, failed]);

  const toggle = () => {
    const next = !expanded;
    setTouched(true);
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  return (
    <div className={`w-full ${className}`} {...props}>
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={panelId}
        onClick={toggle}
        className={`cursor-pointer -mx-1.5 flex w-[calc(100%+0.75rem)] items-center gap-2 rounded-lg px-1.5 py-1 text-left transition-colors hover:bg-accent ${FOCUS}`}
      >
        <ListChecks
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground"
        />
        <span className="text-[13px] font-medium text-foreground">{title}</span>
        <span
          aria-hidden="true"
          className="ml-auto flex items-baseline font-mono text-[11.5px] tabular-nums text-muted-foreground"
        >
          <NumberRoll value={done} duration={600} />
          &nbsp;of&nbsp;
          <NumberRoll value={tasks.length} duration={600} />
          <span
            className="grid"
            style={{
              gridTemplateColumns: settled ? "1fr" : "0fr",
              opacity: settled ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
            }}
          >
            <span className="min-w-0 overflow-hidden whitespace-nowrap">
              &nbsp;done
            </span>
          </span>
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none ${expanded ? "rotate-180" : ""}`}
        />
      </button>
      {/* Outside the button, so its name stays the title. */}
      <span role="status" aria-live="polite" className="sr-only">
        {settled
          ? `${done} of ${tasks.length} done`
          : `${done} of ${tasks.length}`}
      </span>

      <div
        aria-hidden="true"
        className="mt-1.5 h-px w-full overflow-hidden bg-border"
      >
        <div
          className="h-full bg-foreground transition-[width] duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none"
          style={{
            width: `${tasks.length ? (done / tasks.length) * 100 : 0}%`,
          }}
        />
      </div>

      <div
        id={panelId}
        inert={!expanded}
        className={`grid transition-[grid-template-rows,opacity] duration-[400ms] ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none ${
          expanded ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
        }`}
      >
        <div className="overflow-hidden">
          <ol aria-label={title} className="flex flex-col gap-0.5 pt-2.5">
            {tasks.map((task, i) => {
              const quiet = task.status === "done" || task.status === "skipped";
              return (
                <li
                  key={task.id ?? `${i}-${task.label}`}
                  className="flex gap-2.5 py-1"
                >
                  <span className="mt-[3px] flex">
                    <Mark status={task.status} reduced={reduced} />
                  </span>
                  <span className="min-w-0">
                    <span className="block text-[13px] leading-5">
                      {/* The strike draws itself across each line of the label, left to right. */}
                      <span
                        className={`bg-[linear-gradient(var(--border),var(--border))] bg-no-repeat [background-position:0_58%] [box-decoration-break:clone] [-webkit-box-decoration-break:clone] ${
                          quiet
                            ? "text-muted-foreground"
                            : task.status === "pending"
                              ? "text-foreground/70"
                              : "text-foreground"
                        }`}
                        style={{
                          backgroundSize: quiet ? "100% 1px" : "0% 1px",
                          transition: reduced
                            ? "none"
                            : `background-size 520ms ${MORPH} 120ms, color 300ms`,
                        }}
                      >
                        {task.label}
                      </span>
                      <span className="sr-only">
                        , {STATUS_TEXT[task.status]}
                      </span>
                    </span>
                    <Detail
                      text={task.detail}
                      failed={task.status === "failed"}
                      reduced={reduced}
                    />
                  </span>
                </li>
              );
            })}
          </ol>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

